Looking at this problem, I need to:
1. Read a manifest JSON file specifying pairs (rule_id::entity) and facts to extract
2. Load JSON files from the packet directory
3. For each pair, find matching records by `generated_unique_award_id`
4. Extract specified fields and format them appropriately (dates as YYYY-MM-DD, amounts as decimal strings)
5. Handle ABSENT (null/missing), CONFLICT (disagreeing values), or return [value, document]

Let me trace through the logic:
- The entity in each pair matches the `generated_unique_award_id` field in `usaspending_awards.json`
- For `usa.period_3y`: extract `period_of_performance.start_date` and `period_of_performance.end_date`
- For `usa.obligated_95`: extract `total_obligation` and `base_and_all_options`
- Document name is the filename without `.json` extension

```python
import json
import os
import sys
from decimal import Decimal
from datetime import datetime

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    # Load and index documents by generated_unique_award_id
    doc_indices = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith('.json'):
            doc_name = filename[:-5]
            filepath = os.path.join(packet_dir, filename)
            with open(filepath) as f:
                data = json.load(f)

            records = data if isinstance(data, list) else [data]
            doc_indices[doc_name] = {}
            for record in records:
                if isinstance(record, dict):
                    entity_id = record.get('generated_unique_award_id')
                    if entity_id is not None:
                        doc_indices[doc_name].setdefault(entity_id, []).append(record)

    # Fact extraction rules: document, field_path, type
    fact_rules = {
        'usa.period_3y': {
            'performance start': {
                'document': 'usaspending_awards',
                'field_path': ['period_of_performance', 'start_date'],
                'type': 'date'
            },
            'performance end': {
                'document': 'usaspending_awards',
                'field_path': ['period_of_performance', 'end_date'],
                'type': 'date'
            }
        },
        'usa.obligated_95': {
            'amount obligated': {
                'document': 'usaspending_awards',
                'field_path': ['total_obligation'],
                'type': 'amount'
            },
            'potential value': {
                'document': 'usaspending_awards',
                'field_path': ['base_and_all_options'],
                'type': 'amount'
            }
        }
    }

    result = {}
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::', 1)
        facts = manifest['facts'][rule_id]

        result[pair] = {}

        for fact_name in facts:
            rule = fact_rules[rule_id][fact_name]
            doc_name = rule['document']
            field_path = rule['field_path']
            value_type = rule['type']

            matching_records = doc_indices.get(doc_name, {}).get(entity, [])

            if not matching_records:
                result[pair][fact_name] = "ABSENT"
                continue

            values = []
            for record in matching_records:
                value = record
                for key in field_path:
                    if isinstance(value, dict):
                        value = value.get(key)
                    else:
                        value = None
                        break

                if value is None:
                    values.append(None)
                elif value_type == 'date':
                    if isinstance(value, str):
                        try:
                            dt = datetime.strptime(value.split(' ')[0], '%Y-%m-%d')
                            values.append(dt.strftime('%Y-%m-%d'))
                        except ValueError:
                            values.append(value)
                    else:
                        values.append(str(value))
                elif value_type == 'amount':
                    values.append(str(Decimal(str(value))))
                else:
                    values.append(str(value))

            non_none_values = [v for v in values if v is not None]
            if not non_none_values:
                result[pair][fact_name] = "ABSENT"
            elif len(set(non_none_values)) > 1:
                result[pair][fact_name] = "CONFLICT"
            else:
                result[pair][fact_name] = [non_none_values[0], doc_name]

    print(json.dumps(result))

if __name__ == '__main__':
    main()
