Looking at this problem, I need to:
1. Read the manifest to get pairs (rule_id::entity) and facts per rule
2. Load `usaspending_awards.json` and index awards by `generated_unique_award_id`
3. For each pair, extract the specified facts from matching awards
4. Handle ABSENT (null/missing), CONFLICT (disagreeing values), and normal values
5. Format dates as YYYY-MM-DD and amounts as decimal strings

Key observations:
- `performance start` → `period_of_performance.start_date`
- `performance end` → `period_of_performance.end_date`
- `amount obligated` → `total_obligation` (USD)
- `potential value` → `base_and_all_options` (USD)
- Null values mean ABSENT; 0.0 is a valid value
- Document name is `usaspending_awards` (filename without extension)

```python
import json
import sys
import os
from decimal import Decimal

def format_date(value):
    if value is None:
        return None
    return str(value)[:10]

def format_amount(value):
    if value is None:
        return None
    return str(Decimal(str(value)))

def extract_fact(rule_id, fact_name, award):
    if rule_id == "usa.period_3y":
        pop = award.get("period_of_performance") or {}
        if fact_name == "performance start":
            return format_date(pop.get("start_date"))
        elif fact_name == "performance end":
            return format_date(pop.get("end_date"))
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            return format_amount(award.get("total_obligation"))
        elif fact_name == "potential value":
            return format_amount(award.get("base_and_all_options"))
    return None

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    with open(awards_path) as f:
        awards = json.load(f)

    awards_by_id = {}
    for award in awards:
        uid = award.get("generated_unique_award_id")
        if uid:
            awards_by_id.setdefault(uid, []).append(award)

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"][rule_id]

        result[pair] = {}

        matching_awards = awards_by_id.get(entity, [])

        for fact_name in facts:
            values = []

            for award in matching_awards:
                value = extract_fact(rule_id, fact_name, award)
                if value is not None:
                    values.append((value, "usaspending_awards"))

            if not values:
                result[pair][fact_name] = "ABSENT"
            else:
                unique_values = set(v for v, d in values)
                if len(unique_values) > 1:
                    result[pair][fact_name] = "CONFLICT"
                else:
                    result[pair][fact_name] = [values[0][0], values[0][1]]

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
