    documents = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith('.json'):
            doc_name = filename[:-5]
            with open(os.path.join(packet_dir, filename), encoding='utf-8') as f:
                documents[doc_name] = json.load(f, parse_float=Decimal, parse_int=Decimal)

    # Fact field mappings: rule_id -> fact_name -> (document, field_path)
    fact_fields = {
        "usa.period_3y": {
            "performance start": ("usaspending_awards", ("period_of_performance", "start_date")),
            "performance end": ("usaspending_awards", ("period_of_performance", "end_date")),
        },
        "usa.obligated_95": {
            "amount obligated": ("usaspending_awards", ("total_obligation",)),
            "potential value": ("usaspending_awards", ("base_and_all_options",)),
        },
    }

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])

        fact_results = {}
        for fact_name in facts:
            mapping = fact_fields.get(rule_id, {}).get(fact_name)
            if mapping is None:
                fact_results[fact_name] = "ABSENT"
                continue

            doc_name, field_path = mapping

            doc_data = documents.get(doc_name)
            if doc_data is None:
                fact_results[fact_name] = "ABSENT"
                continue

            if not isinstance(doc_data, list):
                doc_data = [doc_data]

            matching_records = [
                r for r in doc_data 
                if isinstance(r, dict) and r.get("generated_unique_award_id") == entity
            ]

            non_null_values = []
            for record in matching_records:
                val = record
                for key in field_path:
                    if isinstance(val, dict):
                        val = val.get(key)
                    else:
                        val = None
                        break
                if val is not None:
                    non_null_values.append(val)

            if not non_null_values:
                fact_results[fact_name] = "ABSENT"
            else:
                unique_values = set(non_null_values)
                if len(unique_values) > 1:
                    fact_results[fact_name] = "CONFLICT"
                else:
                    val_str = str(non_null_values[0])
                    fact_results[fact_name] = [val_str, doc_name]

        result[pair] = fact_results

    print(json.dumps(result))

