import json
import sys
import os

def get_nested_value(obj, path):
    current = obj
    for key in path:
        if current is None:
            return None
        if isinstance(current, dict):
            current = current.get(key)
        else:
            return None
    return current

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    pairs = manifest['pairs']
    facts_by_rule = manifest['facts']

    fact_config = {
        "usa.period_3y": {
            "performance start": ("usaspending_awards", ("period_of_performance", "start_date")),
            "performance end": ("usaspending_awards", ("period_of_performance", "end_date")),
        },
        "usa.obligated_95": {
            "amount obligated": ("usaspending_awards", ("total_obligation",)),
            "potential value": ("usaspending_awards", ("base_and_all_options",)),
        },
    }

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    with open(awards_path, 'r') as f:
        awards = json.load(f)

    awards_by_id = {}
    for award in awards:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            if award_id not in awards_by_id:
                awards_by_id[award_id] = []
            awards_by_id[award_id].append(award)

    result = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        matching_awards = awards_by_id.get(entity, [])

        fact_results = {}
        for fact_name in fact_names:
            config = fact_config.get(rule_id, {}).get(fact_name)
            if config is None:
                fact_results[fact_name] = "ABSENT"
                continue

            document, field_path = config
            values = []
            for award in matching_awards:
                value = get_nested_value(award, field_path)
                if value is not None:
                    values.append(str(value))

            if len(values) == 0:
                fact_results[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                fact_results[fact_name] = [values[0], document]
            else:
                fact_results[fact_name] = "CONFLICT"

        result[pair] = fact_results

    print(json.dumps(result))

if __name__ == "__main__":
    main()
